        let _: T::Assoc = unsafe { std::mem::zeroed() };
    }
}

#[expect(dead_code)]
struct Thing<T: ?Sized>(u64, T);

impl<T: ?Sized> Drop for Thing<T> {
    fn drop(&mut self) {}
}

fn main() {
    <dyn for<'a> Trait<&'a (), Assoc = [Thing<[&'a ()]>; 2]> as Weird>::method();
}
```

